@RunWith(SpringRunner.class)
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_EACH_TEST_METHOD)
@TestPropertySource(locations = "classpath:application-test-multiinstance.properties")
@FixMethodOrder(MethodSorters.NAME_ASCENDING)
public class EventeumEventConsumingIT extends BaseKafkaIntegrationTest {}
/**************TEST SETUP BEGIN*************/
@Before
public void setUp() throws Exception{
    super.setUp();
    final Map<String, Object> consumerProperties = KafkaTestUtils.consumerProps(generateTestGroupId(), "false", embeddedKafka);
    modifyKafkaConsumerProps(consumerProperties);
    DefaultKafkaConsumerFactory<String, String> consumerFactory = new DefaultKafkaConsumerFactory<>(consumerProperties, new StringDeserializer(), new StringDeserializer());
    ContainerProperties containerProperties = new ContainerProperties(kafkaSettings.getContractEventsTopic(), kafkaSettings.getEventeumEventsTopic(), kafkaSettings.getBlockEventsTopic(), kafkaSettings.getTransactionEventsTopic());
    testContainer = new KafkaMessageListenerContainer<>(consumerFactory, containerProperties);
    testContainer.setupMessageListener(new MessageListener<String, String>() {

        @Override
public void onMessage(ConsumerRecord<String, String> record) {
    System.out.println("Received message: " + JSON.stringify(record.value()));
    try {
        if (record.topic().equals(kafkaSettings.getContractEventsTopic())) {
            final EventeumMessage<ContractEventDetails> message = objectMapper.readValue(record.value(), EventeumMessage.class);
            getBroadcastContractEvents().add(message.getDetails());
        }
        if (record.topic().equals(kafkaSettings.getEventeumEventsTopic())) {
            final EventeumMessage message = objectMapper.readValue(record.value(), EventeumMessage.class);
            if (message.getType().equals(ContractEventFilterAdded.TYPE) || message.getType().equals(ContractEventFilterRemoved.TYPE)) {
                final EventeumMessage<ContractEventFilter> filterMessge = message;
                getBroadcastFilterEventMessages().add(filterMessge);
            } else {
                final EventeumMessage<TransactionMonitoringSpec> txMessge = message;
                getBroadcastTransactionEventMessages().add(txMessge);
            }
        }
        if (record.topic().equals(kafkaSettings.getBlockEventsTopic())) {
            final EventeumMessage<BlockDetails> message = objectMapper.readValue(record.value(), EventeumMessage.class);
            getBroadcastBlockMessages().add(message.getDetails());
        }
        if (record.topic().equals(kafkaSettings.getTransactionEventsTopic())) {
            final EventeumMessage<TransactionDetails> message = objectMapper.readValue(record.value(), EventeumMessage.class);
            getBroadcastTransactionMessages().add(message.getDetails());
        }
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}
    });
    testContainer.start();
    ContainerTestUtils.waitForAssignment(testContainer, embeddedKafka.getPartitionsPerTopic() * testContainer.getContainerProperties().getTopics().length);
    final MessageListenerContainer defaultContainer = registry.getListenerContainer(KAFKA_LISTENER_CONTAINER_ID);
    if (defaultContainer != null) {
        ContainerTestUtils.waitForAssignment(defaultContainer, embeddedKafka.getPartitionsPerTopic());
    }
    registry.getListenerContainers().forEach( container -> {
        try {
            if (container != defaultContainer) {
                ContainerTestUtils.waitForAssignment(container, 3);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    });
    clearMessages();
}
