@Test
public void testTxMonitorAddedEventRegistersMonitor() throws Exception{

        final String signedTxHex = createRawSignedTransactionHex();
        final String txHash = Hash.sha3(signedTxHex);

        final TransactionMonitoringSpec spec = new TransactionMonitoringSpec();
        spec.setNodeName("default");
        spec.setTransactionIdentifierValue(txHash);
        spec.setType(TransactionIdentifierType.HASH);

        broadcaster.broadcastTransactionMonitorAdded(spec);

        waitForTransactionMonitorEventMessages(1);

        assertEquals(txHash, sendRawTransaction(signedTxHex));

        waitForTransactionMessages(1);

        assertEquals(1, getBroadcastTransactionMessages().size());

        final TransactionDetails txDetails = getBroadcastTransactionMessages().get(0);
        assertEquals(txHash, txDetails.getHash());
        assertEquals(TransactionStatus.UNCONFIRMED, txDetails.getStatus());
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
protected String createRawSignedTransactionHex() throws ExecutionException, InterruptedException{
        return createRawSignedTransactionHex(ZERO_ADDRESS);
    }
protected String sendRawTransaction(String signedTxHex) throws ExecutionException, InterruptedException{
        final EthSendTransaction ethSendTransaction = web3j.ethSendRawTransaction(signedTxHex).sendAsync().get();
        return ethSendTransaction.getTransactionHash();
    }
protected void waitForTransactionMessages(int expectedTransactionMessages){
        waitForMessages(expectedTransactionMessages, getBroadcastTransactionMessages());
    }
protected List<TransactionDetails> getBroadcastTransactionMessages(){
        return broadcastTransactionMessages;
    }
/**************TEST HELPER METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@After
public void tearDown(){
    testContainer.stop();
}
@After
public void cleanup(){
    final ArrayList<String> filterIds = new ArrayList<>(registeredFilters.keySet());
    try {
        filterIds.forEach( filterId -> unregisterEventFilter(filterId));
    } catch (Throwable t) {
        t.printStackTrace();
    }
    filterRepo.deleteAll();
    if (eventDetailsRepository != null) {
        eventDetailsRepository.deleteAll();
    }
    try {
        new ArrayList<>(registeredTransactionMonitorIds).forEach(this::unregisterTransactionMonitor);
    } catch (Throwable t) {
        t.printStackTrace();
    }
}
