public static void teardownEnvironment() throws Exception{
    StubEventStoreService.stop();
    shouldPersistNodeVolume = true;
    stopParity();
    try {
        final File file = new File(PARITY_VOLUME_PATH);
        FileUtils.deleteDirectory(file);
    } catch (Throwable t) {
    }
}
